    cat:`<circle cx="30" cy="30" r="30" fill="#FFF0D9"/><path d="M11 18 L16 3 L25 13 Z" fill="#E8A25E"/><path d="M49 18 L44 3 L35 13 Z" fill="#E8A25E"/><path d="M14 15 L17 7 L22 12 Z" fill="#FFDCA8"/><path d="M46 15 L43 7 L38 12 Z" fill="#FFDCA8"/><circle cx="21" cy="31" r="2.5" fill="#4A3A2E"/><circle cx="39" cy="31" r="2.5" fill="#4A3A2E"/><path d="M28 37 h4 l-2 2.6 z" fill="#D97B4F"/><path d="M24 42 Q30 46 36 42" stroke="#4A3A2E" stroke-width="1.5" fill="none" stroke-linecap="round"/><path d="M8 34 h9 M8 39 h9 M43 34 h9 M43 39 h9" stroke="#D9B98E" stroke-width="1.3"/>`,
    fox:`<circle cx="30" cy="30" r="30" fill="#FFE3D2"/><path d="M9 20 L14 2 L26 12 Z" fill="#E8794A"/><path d="M51 20 L46 2 L34 12 Z" fill="#E8794A"/><ellipse cx="30" cy="42" rx="15" ry="11" fill="#FFF6EE"/><path d="M20 29 Q23 26 26 29" stroke="#4A3020" stroke-width="2.2" fill="none" stroke-linecap="round"/><path d="M34 29 Q37 26 40 29" stroke="#4A3020" stroke-width="2.2" fill="none" stroke-linecap="round"/><path d="M27 36 h6 l-3 4 z" fill="#7A4630"/><path d="M25 44 Q30 47 35 44" stroke="#7A4630" stroke-width="1.5" fill="none" stroke-linecap="round"/>`,
    panda:`<circle cx="30" cy="30" r="30" fill="#F4F4F1"/><circle cx="13" cy="12" r="8" fill="#33323B"/><circle cx="47" cy="12" r="8" fill="#33323B"/><ellipse cx="21" cy="29" rx="6.4" ry="8" fill="#33323B" transform="rotate(-14 21 29)"/><ellipse cx="39" cy="29" rx="6.4" ry="8" fill="#33323B" transform="rotate(14 39 29)"/><circle cx="22" cy="28" r="2.4" fill="#fff"/><circle cx="38" cy="28" r="2.4" fill="#fff"/><ellipse cx="30" cy="38" rx="3.4" ry="2.6" fill="#33323B"/><path d="M26 43 Q30 46 34 43" stroke="#33323B" stroke-width="1.6" fill="none" stroke-linecap="round"/>`,
