/* ================= 渲染：案例 / 成长 / 朋友 / 消息 / 我的 ================= */
function caseThumb(c){
  const M=c.media||[];
  const first=M[0];
  /* 云端/新发布的案例：用真实首图当封面 */
  if(first&&(first.kind==="img"||first.kind==="image")&&(first.thumbUrl||first.url))
    return `<img class="c-photo" src="${esc(first.thumbUrl||first.url)}" loading="lazy" alt=""><span class="c-type">🖼 图片</span>`;
  if(first&&first.kind==="video"&&first.url)
    return `<video class="c-photo" src="${esc(first.url)}" muted preload="none"${first.thumbUrl?` poster="${esc(first.thumbUrl)}"`:""}></video><span class="c-type">▶ ${c.dur||"0:30"}</span>`;
  if(first&&first.kind==="file")
    return `<div class="c-doc">📄<span>${esc((first.name||"PPT").replace(/\.[^.]+$/,""))}</span></div><span class="c-type">📊 文件</span>`;
  if(c.type==="ppt")return pptThumb();
  /* 图文案例（casedit 层）：有正文无配图时不要谎称「图片」，如实标图文 */
  if(!first&&String(c.content_html||"").trim())return `${scene(c.kind||"study")}<span class="c-type">📝 图文</span>`;
  const svg=scene(c.kind||"study");
  if(c.type==="video")return `${svg}<span class="c-type">▶ ${c.dur||"0:30"}</span>`;
  return `${svg}<span class="c-type">🖼 图片</span>`;
}
function renderCases(){
  const f=S.curCaseFilter;
  const list=S.cases.filter(c=>f==="all"||c.type===f);
  let empty="";
  if(!list.length){
    const st=(function(){try{return window.YRB_CLOUD&&YRB_CLOUD.casesState?YRB_CLOUD.casesState():"ok";}catch(e){return "ok";}})();
    if(st==="loading")empty=`<div class="empty">⏳ 正在加载案例…</div>`;
    else if(st==="isolated")empty=`<div class="empty">🛠 云端服务正在维护，案例暂时显示不了<br><button type="button" class="btn-a" id="casesRetry" style="margin-top:12px">↻ 立即重试</button><div style="font-size:12.5px;color:#999;margin-top:8px;line-height:1.6">页面每 20 秒自动重试一次<br>服务恢复后会自己刷新，不用一直点</div></div>`;
    else if(st==="fail")empty=`<div class="empty">⚠️ 案例加载失败，可能是网络不稳定<br><button type="button" class="btn-a" id="casesRetry" style="margin-top:12px">↻ 点此重试</button></div>`;
    else empty=`<div class="empty">暂无该类型案例</div>`;
  }
  $("#caseGrid").innerHTML=(list.length?list.map(c=>`<div class="case-card" data-act="case" data-i="${S.cases.indexOf(c)}">
    <div class="c-thumb">${caseThumb(c)}</div>
    <div class="c-info"><div class="c-title">${esc(c.t)}</div>
    <div class="c-by"><span class="ca">${avatarSVG(c.ava)}</span>${esc(c.by)}</div>
    <div class="c-stats"><span>🤝 <b>${c.helps}</b></span><span>♥ <b>${c.likes}</b></span><span>⭐ <b>${c.favs}</b></span></div></div>
  </div>`).join(""):"")+empty;
}
$("#caseGrid").addEventListener("click",e=>{
  if(e.target.closest&&e.target.closest("#casesRetry")){
    e.stopPropagation();
    try{if(window.YRB_CLOUD&&YRB_CLOUD.retryCases)YRB_CLOUD.retryCases();}catch(err){}
  }
});
function renderGrowth(){
  $("#tlList").innerHTML=S.growth.length?S.growth.map(g=>`<div class="tl-item"><span class="tl-dot"></span>
    <div class="tl-card"><div class="tl-date">${esc(g.d)}</div><div class="tl-t">${esc(g.e)} ${esc(g.t)}</div><div class="tl-d">${esc(g.d2)}</div></div></div>`).join("")
    :`<div class="empty">🌱 还没有成长记录，记下孩子的每一个第一次吧</div>`;
}
