/* ================= 帮忙评论 ================= */
function cmItemHTML(c,i){
  /* 真实媒体优先：帮忙里录下的语音/视频/图片直接可播放（本地录制或云端签名地址） */
  const real=(c.media||[]).filter(m=>m&&m.url);
  let body;
  if(real.length){
    if(c.kind==="video"){
      body=`<div class="cm-media cm-real"><video src="${esc(real[0].url)}" controls playsinline preload="none"${real[0].thumbUrl?` poster="${esc(real[0].thumbUrl)}"`:""}></video><span class="vd-chip">▶ ${esc(c.dur||"")}</span></div>`;
    }else if(c.kind==="voice"){
      body=`<div class="cm-media cm-real"><span class="cm-rv">🎙️</span><audio src="${esc(real[0].url)}" controls preload="metadata"></audio><span class="vd-chip">${esc(c.dur||"")}</span></div>`;
    }else{
      body=`<div class="cm-media cm-real"><img src="${esc(real[0].thumbUrl||real[0].url)}" data-full="${esc(real[0].url)}" alt="帮忙图片" loading="lazy"></div>`;
    }
  }else if(c.kind==="voice"){
    let bars="";for(let k=0;k<12;k++)bars+=`<i style="height:${20+Math.round(Math.abs(Math.sin(k*1.9))*70)}%;width:3px;flex:none;border-radius:99px;background:var(--accent2);opacity:.6"></i>`;
    body=`<div class="cm-media"><div class="bars" style="gap:2.5px">${bars}</div><span class="vd-chip">🎤 ${c.dur}</span></div>`;
  }else if(c.kind==="video"){
    body=`<div class="cm-media">🎬<b style="font-size:13px">微视频帮忙</b><span class="vd-chip">${c.dur} · ≤20s</span></div>`;
  }else body=`<div class="cm-content">${esc(c.text)}</div>`;
  return `<div class="cm-item">
    <div class="cm-ava">${c.user==="阳阳爸爸"?myAvaSVG():avatarSVG(c.ava)}</div>
    <div class="cm-main"><div class="cm-name">${esc(c.user)} ${esc(c.flag||"")} <span class="cm-kind">帮忙</span></div>
    ${body}
    <div class="cm-acts">
      <button class="clike ${c.liked?"on":""}" data-act="clike" data-i="${i}">♥ <span>${c.likes+(c.liked?1:0)}</span></button>
      <button class="gift" data-act="cgift">🍽️ 送美食</button>
    </div></div>
  </div>`;
}
function renderComments(){
  const p=S.posts.find(x=>x.id===S.curPost);if(!p)return;
  $("#cmTitle").textContent=`帮忙 · ${p.user}的求助（${p.helps}）`;
  $("#cmList").innerHTML=p.comments.map(cmItemHTML).join("")||`<div class="empty">还没有帮忙，来说第一句温暖的话吧</div>`;
}
function addComment(c){
  const p=S.posts.find(x=>x.id===S.curPost);if(!p)return;
  if(c&&typeof c==="object")c.mine=true;   /* 本机发起的帮忙均标记为「我的帮忙」，供「我的」页归档 */
  p.comments.push(c);p.helps++;
  const pill=$(`.card[data-id="${p.id}"] .helps-pill`);if(pill)pill.textContent=`🤝 ${p.helps} 个帮忙`;
  renderComments();toast("帮忙已送达，感谢你的善意 🌸");
}

/* ================= 发布 ================= */
function pubPreview(){
  const t=S.pubType,box=$("#pubPrev");
  if(t==="img")box.innerHTML=`<div class="media m-imgs n2">${scene("study")}${scene("garden")}</div>`;
  else if(t==="video")box.innerHTML=`<div class="media m-video" data-act="video">${scene("heart")}<span class="v-play"><svg viewBox="0 0 24 24"><path d="M7 4 L20 12 L7 20 Z"/></svg></span><span class="v-dur">▶ 0:24 · ≤30s</span><span class="v-prog"></span></div>`;
  else{let bars="";for(let i=0;i<22;i++)bars+=`<i style="height:${18+Math.round(Math.abs(Math.sin(i*1.7))*74)}%"></i>`;box.innerHTML=`<div class="media m-voice" data-act="voice"><span class="vp"><svg viewBox="0 0 24 24"><path d="M7 4 L20 12 L7 20 Z"/></svg></span><div class="bars">${bars}</div><span class="vd-chip">语音 0:12</span></div>`;}
}
function doPublish(){
  const txt=$("#pubText").value.trim();
  if(!txt){toast("先写一句求助描述吧～");return;}
  const t=S.pubType;
  const p={id:uid(),mine:true,user:"阳阳爸爸",flag:S.region.flag,type:t,hot:false,tag:"我的求助",time:"刚刚",loc:`${S.region.city}`,
    text:txt,likes:0,liked:false,favs:0,faved:false,helps:0,comments:[]};
  if(t==="img")p.kinds=["study","garden"];
  if(t==="video"){p.kind="heart";p.dur="0:26";}
  if(t==="voice")p.dur="0:12";
  /* 整体替换而非原地 unshift：保持「posts 只许整体替换」的状态契约（见 state.schema.js），
     语义完全等价（unshift 的返回值此处未使用） */
  S.posts=[p,...S.posts];S.published++;
  $("#pubText").value="";closeSheet("publishSheet");
  switchTab("home");S.hotMode=false;renderFuncRow();renderFeed();
  toast("发布成功，等待温柔的帮忙 🌸");
}
