/* ================= 页面切换 ================= */
function switchTab(p){
  $$(".page").forEach(x=>x.classList.toggle("active",x.id==="page-"+p));
  $$(".tb-item").forEach(b=>b.classList.toggle("active",b.dataset.p===p));
  if(p==="msgs"){renderMsgs();setTimeout(clearUnread,600);}
  if(p==="cases")renderCases();
  if(p==="growth")renderGrowth();
  if(p==="me")renderMe();
  closeDropdown();closeDrawer();
}

/* ================= sheet / drawer / dropdown ================= */
/* 打开任何弹层前，先暂停所有媒体并退出全屏（2026-10-19 用户反馈：
   刚浏览的视频还在全屏播放时就点 + 发布，全屏画面盖住发布面板、也挡住语音转文字按钮） */
function stopAllMedia(){
  try{
    document.querySelectorAll("video,audio").forEach(v=>{try{v.pause();}catch(e){}});
    const d=document;
    if(d.fullscreenElement&&d.exitFullscreen){const p=d.exitFullscreen();if(p&&p.catch)p.catch(()=>{});}
    else if(d.webkitFullscreenElement&&d.webkitExitFullscreen){try{d.webkitExitFullscreen();}catch(e){}}
  }catch(e){}
}
function openSheet(id){stopAllMedia();$("#"+id).classList.add("open");maskFor(id,true);}
function closeSheet(id){$("#"+id).classList.remove("open");maskFor(id,false);}
function maskFor(id,on){
  const anyOpen=["publishSheet","commentSheet","funcAddSheet","caseUpSheet"].some(x=>$("#"+x).classList.contains("open"));
  $("#drMask").classList.toggle("show",on||anyOpen);
}
function openDrawer(){$("#drawer").classList.add("open");$("#drMask").classList.add("show");}
function closeDrawer(){$("#drawer").classList.remove("open");if(!$$(".sheet.open").length)$("#drMask").classList.remove("show");}
function openDropdown(){renderDropdown();$("#dropdown").classList.add("open");}
function closeDropdown(){$("#dropdown").classList.remove("open");}

