/* ================= 案例查看 ================= */
let slideIdx=0;
function vwLock(){
  return `<div class="vw-lock">🔒 <b>登录后可查看案例内容</b><span>案例素材保存在云端，登录后即可浏览</span>
    <button class="btn-a" data-vwlogin="1">登录 / 注册</button></div>`;
}
function openViewer(c){
  $("#vwTitle").textContent=c.t;
  slideIdx=0;
  const M=c.media||[];
  const stats=`<div class="c-stats" style="justify-content:center;font-size:13px"><span>🤝 <b>${c.helps||0}</b></span><span>♥ <b>${c.likes||0}</b></span><span>⭐ <b>${c.favs||0}</b></span></div>`;
  if(M.length){
    if(c.type==="video"){
      const v=M[0];
      $("#vwBody").innerHTML=(v.url
        ?`<video src="${esc(v.url)}" controls playsinline preload="metadata" style="width:100%;max-height:56vh;border-radius:14px;background:#000;display:block"></video>`
        :vwLock())+stats;
    }else if(c.type==="ppt"&&M[0].kind==="file"){
      const f=M[0];
      /* 云端早期数据没存 name：从 path 尾段推出文件名（含扩展名，供格式判断） */
      const fname=f.name||(f.path?f.path.split("/").pop():"")||"演示文件";
      /* 2026-10-22：PPT 自动展开逐页浏览（pptview 层），失败自动降级为文件卡片
         2026-10-24：内容保护——「打开文件」只给管理员，普通用户不暴露原文件地址 */
      $("#vwBody").innerHTML=(f.url
        ?`<div class="vp-wrap" id="vpWrap"></div>`
        :vwLock())+stats;
      $("#viewer").classList.add("open");
      if(f.url){
        if(window.YRB_PPT)YRB_PPT.mount($("#vpWrap"),{url:f.url,path:f.path||"",name:fname});
        else{
          const isAdmin=(()=>{try{return !!(window.YRB_CONSOLE&&YRB_CONSOLE.isAdmin&&YRB_CONSOLE.isAdmin())||!!(window.YRB_ADMINGUARD&&YRB_ADMINGUARD.unlocked&&YRB_ADMINGUARD.unlocked());}catch(e){return false;}})();
          $("#vpWrap").innerHTML=`<div class="vp-fail"><b>📄</b><span>${esc(fname)}</span>
            ${isAdmin?`<a class="btn-a" href="${esc(f.url)}" target="_blank" rel="noopener">打开文件</a>`:""}
            <i>内容暂时无法展开，请稍后重试</i></div>`;
        }
      }
      return;
    }else{
      /* 图片案例（含图片型 PPT）：真实图片墙 */
      const imgs=M.filter(m=>(m.kind==="img"||m.kind==="image")&&m.url);
      $("#vwBody").innerHTML=(imgs.length
        ?`<div class="vw-imgs">${imgs.map(m=>`<img src="${esc(m.url)}" loading="lazy" alt="">`).join("")}</div>`
        :vwLock())+stats;      /* 全部图片都拿不到签名地址（未登录）→ 登录锁 */
    }
    $("#viewer").classList.add("open");
    return;
  }
  if(c.type==="img")$("#vwBody").innerHTML=`<div class="media m-imgs n1">${scene(c.kind||"study")}</div>`+stats;
  else if(c.type==="video")$("#vwBody").innerHTML=`<div class="media m-video" style="height:230px" data-act="video">${scene(c.kind||"study")}<span class="v-play"><svg viewBox="0 0 24 24"><path d="M7 4 L20 12 L7 20 Z"/></svg></span><span class="v-dur">▶ ${c.dur||"0:30"} · ≤30s</span><span class="v-prog"></span></div>`;
  else $("#vwBody").innerHTML=`<div id="slBox"></div><div class="vw-nav" id="slNav"></div>`;
  $("#viewer").classList.add("open");
  if(c.type==="ppt")renderSlides(c);
}
function renderSlides(c){
  const s=c.slides[slideIdx];
  $("#slBox").innerHTML=`<div class="slide"><h3>${s.h}</h3><ul>${s.lis.map(l=>`<li>${l}</li>`).join("")}</ul><div class="s-num">${slideIdx+1} / ${c.slides.length}</div></div>`;
  $("#slNav").innerHTML=c.slides.map((_,i)=>`<span class="dot ${i===slideIdx?"on":""}"></span>`).join("");
  $("#slNav").onclick=e=>{const i=[...$("#slNav").children].indexOf(e.target);if(i>-1){slideIdx=i;renderSlides(c);}};
}

