/* 卡片 ⋯ 菜单：转发链接 / 举报（复用详情页举报浮层，处理函数 refine23 已在启动时绑定） */
function cardMore(p){
  /* 2026-10-29 审核：原来先 esc 再 slice(0,24)，会把 &amp; 截成 &am 露出半截实体。
     正确顺序是先按原文截断、再转义。 */
  const title=esc(String(p.title||p.text||"求助").slice(0,24));
  modal(`<h3 style="margin:0 0 4px;font-size:17px">这条求助</h3>
    <div style="color:var(--muted);font-size:13px;margin-bottom:14px">${title}…</div>
    <button class="btn-a big" id="cmShare" style="margin-bottom:10px">🔗 转发给朋友（复制链接）</button>
    <button class="btn-a big" id="cmReport" style="background:#fff;color:#c2452d;box-shadow:inset 0 0 0 1.5px var(--rule)">🛡 举报该内容</button>`);
  $("#cmShare").addEventListener("click",()=>{
    closeModal();
    const link=location.origin+location.pathname;
    const done=()=>toast("链接已复制，去粘贴给朋友吧 🔗");
    try{
      if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(link).then(done,()=>fallbackCopy(link,done));
      else fallbackCopy(link,done);
    }catch(e){fallbackCopy(link,done);}
  });
  $("#cmReport").addEventListener("click",()=>{
    closeModal();
    try{
      const g=$("#r23RpGrid");
      if(g)g.querySelectorAll("button").forEach(x=>x.classList.remove("on"));
      const ov=$("#r23Report");
      if(ov){ov.classList.add("open");return;}
    }catch(e){}
    toast("请在求助详情里使用「举报」");
  });
}
function fallbackCopy(txt,done){
  try{
    const ta=document.createElement("textarea");
    ta.value=txt;ta.style.position="fixed";ta.style.opacity="0";
    document.body.appendChild(ta);ta.select();
    const ok=document.execCommand("copy");
    document.body.removeChild(ta);
    toast(ok?"链接已复制，去粘贴给朋友吧 🔗":"请复制浏览器地址栏的链接转发");
  }catch(e){toast("请复制浏览器地址栏的链接转发");}
}
