/* ---------- 案例内容选择（2026-10-20：图片 / 视频 / PPT 真实上传） ---------- */
const CU_CONF={
  /* ppt 的 accept 必须带 MIME：安卓文件管理器认 MIME 不认扩展名，只写 .ppt/.pptx/.pdf 会筛得无文件可选 */
  img:{accept:"image/*",multiple:true,max:9,note:"选几张图片（最多 9 张）",add:"加图片"},
  ppt:{accept:".ppt,.pptx,.pdf,application/vnd.ms-powerpoint,application/vnd.openxmlformats-officedocument.presentationml.presentation,application/pdf",multiple:false,note:"选一个 PPT / PDF 文件（≤8MB）",add:"选文件"},
  video:{accept:"video/*",multiple:false,note:"选一段 ≤20 秒的短视频（用「录视频」现拍体积最小）",add:"选视频"}
};
let cuFiles=[];   /* [{blob,url,name,kind,dur}]  kind: img | video | file */
function cuShort(n){return n&&n.length>14?n.slice(0,6)+"…"+n.slice(-6):n||"文件";}
function cuAccept(){
  const c=CU_CONF[S.cuType]||CU_CONF.img,inp=$("#cuFile");
  if(inp){inp.accept=c.accept;inp.multiple=!!c.multiple;}
  const n=$("#cuNote");if(n)n.textContent=c.note;
  renderCuGrid();
}
function renderCuGrid(){
  const g=$("#cuGrid");if(!g)return;
  const c=CU_CONF[S.cuType]||CU_CONF.img;
  const tiles=cuFiles.map((f,i)=>`<span class="cu-tile">${
    f.kind==="img"?`<img src="${f.url}" alt="">`:
    f.kind==="video"?`<video src="${f.url}" muted preload="metadata"></video><i class="cu-play">▶</i>`:
    `<b class="cu-doc">📄</b><u>${esc(cuShort(f.name))}</u>`
  }<em data-cux="${i}" title="移除">✕</em></span>`).join("");
  const room=cuFiles.length<(c.max||1);
  /* 2026-10-25：+ 改为 <label> 内嵌 <input type=file> 原生触发。
     微信 X5 / 部分安卓 WebView 会拦 display:none 输入框的 JS click()，
     而发布求助用 label 包裹一直正常——案例上传对齐同款写法（同 capture.js）。 */
  g.innerHTML=tiles+(room?`<label class="cu-add">＋<span>${c.add}</span><input type="file" class="cu-in" accept="${c.accept}"${c.multiple?" multiple":""} hidden></label>`:"");
}
function cuClear(){
  cuFiles.forEach(f=>{try{URL.revokeObjectURL(f.url);}catch(e){}});
  cuFiles=[];
}
function videoDur(file){
  return new Promise(res=>{
    try{
      const v=document.createElement("video"),u=URL.createObjectURL(file);
      const done=d=>{URL.revokeObjectURL(u);res(d);};
      v.preload="metadata";v.muted=true;
      v.onloadedmetadata=()=>done(v.duration||0);
      v.onerror=()=>done(0);
      setTimeout(()=>done(0),6000);
      v.src=u;
    }catch(e){res(0);}
  });
}
$("#cuGrid").addEventListener("click",e=>{
  const rm=e.target.closest("[data-cux]");
  if(rm){const i=+rm.dataset.cux;const f=cuFiles[i];if(f){try{URL.revokeObjectURL(f.url);}catch(err){}cuFiles.splice(i,1);renderCuGrid();}return;}
  /* + 的文件选择由 label 原生触发，不再 JS click()（微信 X5 兼容） */
});
/* 静态 #cuFile 与 label 内动态 .cu-in 都走 change 委托（label 输入每次重渲染都会重建） */
async function handleCuFiles(files){
  if(!files.length)return;
  const conf=CU_CONF[S.cuType]||CU_CONF.img;
  if(S.cuType==="img"){
    const cap=(CU_CONF.img.max||9)-cuFiles.length;
    const take=files.slice(0,cap);
    if(files.length>cap)toast(`最多 ${CU_CONF.img.max||9} 张，已为您保留前 ${cap} 张`);
    if(!take.length)return;
    toast("正在压缩图片…");
    for(const f of take){
      let out=f;
      try{if(window.YRB_CAPTURE&&YRB_CAPTURE.compress)out=await YRB_CAPTURE.compress(f);}catch(err){}
      cuFiles.push({blob:out,url:URL.createObjectURL(out),name:out.name||"photo.jpg",kind:"img"});
      renderCuGrid();
    }
    toast(`已添加 ${take.length} 张图片`);
  }else if(S.cuType==="video"){
    const f=files[0];
    if(cuFiles.length){toast("一个案例只放一段视频，已替换原来的");cuClear();}
    toast("正在检查视频时长…");
    const d=await videoDur(f);
    if(d>21){toast(`这段视频 ${Math.round(d)} 秒，超过 20 秒了，请剪短一点再传`);return;}
    /* 额度节流（2026-10-26 免费额度专项）：视频是最大的流量消耗项。
       用 App 里直接录制约 2MB/20 秒；相册里的 1080p 原片常常 20-30MB，
       几十次播放就能吃掉免费额度的一大块，所以门槛从 15MB 收到 8MB。 */
    if(f.size>8*1024*1024){
      toast(`这段视频 ${(f.size/1048576).toFixed(1)}MB，太大了。建议用「录视频」现拍一段（体积小、也清楚）`);
      return;
    }
    cuFiles.push({blob:f,url:URL.createObjectURL(f),name:f.name||"video",kind:"video",dur:fmtDur(d)});
    renderCuGrid();
  }else{
    const f=files[0];
    if(!/\.(pptx?|pdf)$/i.test(f.name||"")){toast("请选择 PPT（.ppt/.pptx）或 PDF 文件");return;}
    /* 免费额度专项（2026-10-26）：PPT/PDF 每次打开都要下载整个文件，
       20MB 的课件被看 30 次就是 600MB 流量。8MB 以内通常够放 20-30 页图文课件。 */
    if(f.size>8*1024*1024){toast("文件超过 8MB 了，请在电脑上压缩（或另存为 PDF）后再传");return;}
    if(cuFiles.length)cuClear();
    cuFiles.push({blob:f,url:URL.createObjectURL(f),name:f.name,kind:"file"});
    renderCuGrid();
  }
}
document.addEventListener("change",e=>{
  const t=e.target;
  if(!t||t.tagName!=="INPUT"||t.type!=="file")return;
  if(t.id!=="cuFile"&&!(t.classList&&t.classList.contains("cu-in")))return;
  const files=[...t.files||[]];t.value="";
  handleCuFiles(files);
});
function fmtDur(sec){
  sec=Math.max(1,Math.round(sec||0));
  return Math.floor(sec/60)+":"+String(sec%60).padStart(2,"0");
}
$("#cuTypes").addEventListener("click",e=>{
  const b=e.target.closest(".seg-btn");if(!b)return;
  if(S.cuType!==b.dataset.t){cuClear();}          /* 换类型清空已选内容，避免图片配到视频案例上 */
  $$("#cuTypes .seg-btn").forEach(x=>x.classList.remove("on"));b.classList.add("on");S.cuType=b.dataset.t;
  cuAccept();
});
$("#cuGo").addEventListener("click",async ()=>{
  const t=$("#cuTitle").value.trim();
  if(!t){toast("先给案例起个标题吧～");return;}
  const goBtn=$("#cuGo");
  const files=cuFiles.slice();
  if(files.length){
    /* 真实上传：需登录 → 云端存储 + yb_cases 入库 */
    const C=window.YRB_CLOUD;
    if(!C||!C.signedIn||!C.signedIn()){
      toast("上传案例内容需要先登录 / 注册～");
      if(C&&C.ensureLogin)setTimeout(()=>{try{C.ensureLogin();}catch(e){}},250);
      return;
    }
    if(goBtn){goBtn.disabled=true;goBtn.textContent="正在发布…";}
    try{
      const res=await C.publishCase({title:t,type:S.cuType},
        files.map(f=>({blob:f.blob,kind:f.kind,dur:f.dur||"",name:f.name})));
      if(res&&res.reason==="auth"){
        toast((res.message||"登录已过期，请重新登录后再上传"));
        if(C.openLogin)setTimeout(()=>{try{C.openLogin();}catch(e){}},800);
        return;
      }
      if(!res||!res.ok){
        toast("发布没成功："+((res&&res.message)||"请检查网络后再试一次"));
        return;
      }
      const first=res.media&&res.media[0];
      /* 铁律：云投影数组只许整体替换（2026-10-29 审核 H1 修复，原 unshift） */
      S.cases=[{t:t,by:(typeof myName==="function"?myName():"家长")||"家长",ava:"rabbit",
        type:S.cuType,kind:"study",dur:(first&&first.dur)||"0:28",
        media:res.media.map(m=>({kind:m.kind,url:m.url,path:m.path,dur:m.dur||""})),
        __cloud:true,cloudId:res.cloudId,helps:0,likes:0,favs:0},...S.cases];
      toast("案例已发布到广场 🎉");
    }catch(err){
      console.warn("[案例发布]",err);
      toast("发布出了点小问题，请再试一次");
      return;
    }finally{
      if(goBtn){goBtn.disabled=false;goBtn.textContent="发布到案例广场";}
    }
  }else{
    /* 纯文字案例：同样要真正存到云端。
       此前这里只塞一条本地假案例且不入库，刷新后就消失——模板期遗留，2026-10-26 修正。 */
    const C=window.YRB_CLOUD;
    if(!C||!C.signedIn||!C.signedIn()){
      toast("发布案例需要先登录 / 注册～");
      if(C&&C.ensureLogin)setTimeout(()=>{try{C.ensureLogin();}catch(e){}},250);
      return;
    }
    if(goBtn){goBtn.disabled=true;goBtn.textContent="正在发布…";}
    try{
      const res=await C.publishCase({title:t,type:S.cuType},[]);
      if(res&&res.reason==="auth"){
        toast((res.message||"登录已过期，请重新登录后再发布"));
        if(C.openLogin)setTimeout(()=>{try{C.openLogin();}catch(e){}},800);
        return;
      }
      if(!res||!res.ok){
        toast("发布没成功："+((res&&res.message)||"请检查网络后再试一次"));
        return;
      }
      /* 铁律：云投影数组只许整体替换（2026-10-29 审核 H1 修复，原 unshift） */
      S.cases=[{t:t,by:(typeof myName==="function"?myName():"家长")||"家长",ava:"rabbit",
        type:S.cuType,kind:"study",dur:"",media:[],
        __cloud:true,cloudId:res.cloudId,helps:0,likes:0,favs:0},...S.cases];
      toast("案例已发布到广场 🎉（这次没有配内容，下次记得选内容哦）");
    }catch(err){
      console.warn("[案例发布]",err);
      toast("发布出了点小问题，请再试一次");
      return;
    }finally{
      if(goBtn){goBtn.disabled=false;goBtn.textContent="发布到案例广场";}
    }
  }
  $("#cuTitle").value="";cuClear();renderCuGrid();
  /* 关键：发布后切回「全部」筛选。否则停在「图片」筛选时发微视频，
     新案例被筛选器藏起来，看起来就像点了没反应、卡在这里（2026-10-19 用户反馈） */
  S.curCaseFilter="all";
  $$("#caseTabs .ct").forEach(x=>x.classList.toggle("on",x.dataset.f==="all"));
  closeSheet("caseUpSheet");
  renderCases();
  const firstCard=$("#caseGrid .case-card");
  if(firstCard){firstCard.classList.add("fresh");setTimeout(()=>firstCard.classList.remove("fresh"),2400);
    try{firstCard.scrollIntoView({block:"nearest",behavior:"smooth"});}catch(e){}}
});
